function useToggle(initialValue = false) {
  const [value, setValue] = useState(initialValue);

  const toggle = () => {
    setValue((prev) => !prev);
  };

  const setTrue = () => {
    setValue(true);
  };

  const setFalse = () => {
    setValue(false);
  };

  return {
    value,
    toggle,
    setTrue,
    setFalse
  };
}

function App() {
  const {
    value,
    toggle,
    setTrue,
    setFalse
  } = useToggle();

  return (
    <>
      <p>{value ? "ON" : "OFF"}</p>
      <button onClick={toggle}>Toggle</button>
      <button onClick={setTrue}>ON</button>
      <button onClick={setFalse}>OFF</button>
    </>
  );
}
